import React, { useEffect, useState } from "react";
import api from "../api";
import { io } from "socket.io-client";

type Ticket = {
  _id: string;
  title: string;
  description: string;
  status: "open" | "in_progress" | "closed";
  category: "billing" | "technical" | "general";
  priority: "low" | "medium" | "high";
  createdBy: string;
  assignee: any;
  createdAt: string;
};
